@prefix xsd: <${xsd}> .
@prefix vc: <${vc}> .

<${vocabulary}CredentialShape> a sh:NodeShape ;
  sh:targetClass <${iri(types.find(type=>type!=='VerifiableCredential')||'VerifiableCredential')}> ;
