function normalizePublicHost(value) {
  const raw = String(value ?? "").trim().toLowerCase().replace(/\.$/, "");
  if (!raw) throw new Error("public host is required");
  if (/^[A-Za-z][A-Za-z0-9+.-]*:/.test(raw) || raw.startsWith("//") || /[/?#@\\\s]/.test(raw)) {
