    const representation = {
      username,
      email: options.email || undefined,
      firstName: options.firstName || undefined,
      lastName: options.lastName || undefined,
      enabled: true,
      emailVerified: Boolean(options.emailVerified),
      requiredActions,
      attributes,
    };
