    ? `/apis/${encodeURIComponent(descriptor.group)}/${encodeURIComponent(descriptor.version)}`
    : `/api/${encodeURIComponent(descriptor.version)}`;
  if (!descriptor.namespaced) return `${base}/${descriptor.plural}`;
  if (!namespace) throw new Error(`Namespace is required for ${descriptor.plural}`);
  return `${base}/namespaces/${encodeURIComponent(namespace)}/${descriptor.plural}`;
}
function mutationNamespace(object, defaultNamespace = "") {
  return object && object.metadata && object.metadata.namespace ? String(object.metadata.namespace) : defaultNamespace;
}
function assertK8sMutationAllowed(object, defaultNamespace = "", options = {}) {
  if (!object || !object.apiVersion || !object.kind || !object.metadata || !object.metadata.name) throw new Error("Kubernetes object requires apiVersion, kind, metadata.name");
  const namespace = mutationNamespace(object, defaultNamespace);
  if (namespace && namespace === cfg.ocmNamespace) throw new Error(`FAP PCI is not permitted to modify the OCM namespace ${cfg.ocmNamespace}`);
  if (options.source === "envoy") return;
  const allowedNamespaces = new Set([cfg.orceNamespace, cfg.infrastructureNamespace, cfg.envoy.namespace]);
  if (namespace && !allowedNamespaces.has(namespace)) throw new Error(`Refusing Kubernetes mutation outside managed namespaces: ${namespace}`);
  const clusterKinds = new Set(["Namespace", "GatewayClass"]);
  if (!namespace && !clusterKinds.has(object.kind)) throw new Error(`Refusing unapproved cluster-scoped mutation: ${object.kind}/${object.metadata.name}`);
}
async function k8sApply(object, defaultNamespace = "", options = {}) {
  assertK8sMutationAllowed(object, defaultNamespace, options);
  const descriptor = await k8sDescriptor(object.apiVersion, object.kind);
  const namespace = descriptor.namespaced ? mutationNamespace(object, defaultNamespace) : "";
  if (descriptor.namespaced && !object.metadata.namespace) object.metadata.namespace = namespace;
  const path = `${k8sCollectionPath(descriptor, namespace)}/${encodeURIComponent(object.metadata.name)}?fieldManager=fap-pci-orce&force=true`;
  return k8sExpect("PATCH", path, {
    headers: { "content-type": "application/apply-patch+yaml" },
    body: yaml.stringify(object),
    timeout: options.timeout || 60000,
  }, [200, 201]);
}
async function k8sGet(apiVersion, kind, name, namespace = "") {
  const descriptor = await k8sDescriptor(apiVersion, kind);
  const path = `${k8sCollectionPath(descriptor, descriptor.namespaced ? namespace : "")}/${encodeURIComponent(name)}`;
  const response = await k8sRequest("GET", path);
  if (response.status === 404) return null;
  if (response.status !== 200) throw new Error(`Kubernetes GET ${kind}/${name} failed with ${response.status}: ${response.data && response.data.message ? response.data.message : response.text}`);
  return response.data;
}
async function k8sList(apiVersion, kind, namespace = "", labelSelector = "") {
  const descriptor = await k8sDescriptor(apiVersion, kind);
  let path = k8sCollectionPath(descriptor, descriptor.namespaced ? namespace : "");
  if (labelSelector) path += `?labelSelector=${encodeURIComponent(labelSelector)}`;
  return k8sExpect("GET", path, {}, [200]);
}
async function k8sDelete(apiVersion, kind, name, namespace = "", options = {}) {
  const descriptor = await k8sDescriptor(apiVersion, kind);
  const fake = { apiVersion, kind, metadata: { name, ...(namespace ? { namespace } : {}) } };
  assertK8sMutationAllowed(fake, namespace, options);
  const path = `${k8sCollectionPath(descriptor, descriptor.namespaced ? namespace : "")}/${encodeURIComponent(name)}`;
  return k8sExpect("DELETE", path, { headers: { "content-type": "application/json" }, body: JSON.stringify({ apiVersion: "v1", kind: "DeleteOptions", propagationPolicy: "Foreground" }) }, [200, 202, 404]);
}
function conditionStatus(object, type) {
  const conditions = object && object.status && Array.isArray(object.status.conditions) ? object.status.conditions : [];
  return conditions.find((condition) => condition.type === type) || null;
}
function routeParentConditions(route) {
  const parents = route && route.status && Array.isArray(route.status.parents) ? route.status.parents : [];
  return parents.flatMap((parent) => Array.isArray(parent.conditions) ? parent.conditions : []);
}
function routeCondition(route, type) {
  return routeParentConditions(route).find((condition) => condition.type === type) || null;
}
async function waitFor(description, predicate, timeoutSeconds = 180, intervalMs = 3000) {
  const deadline = Date.now() + timeoutSeconds * 1000;
  let lastError = null;
  while (Date.now() < deadline) {
    try {
      const value = await predicate();
      if (value) return value;
    } catch (error) { lastError = error; }
    await sleep(intervalMs);
  }
  if (lastError) throw new Error(`${description} timed out: ${lastError.message}`);
  throw new Error(`${description} timed out after ${timeoutSeconds}s`);
}
async function fetchTextWithRedirects(urlValue, redirects = 5) {
  if (redirects < 0) throw new Error("Too many redirects while downloading a pinned manifest");
  const response = await requestRaw(urlValue, { timeout: 45000 });
  if ([301, 302, 303, 307, 308].includes(response.status) && response.headers.location) {
    const next = new URL(response.headers.location, urlValue).toString();
    return fetchTextWithRedirects(next, redirects - 1);
  }
  if (response.status !== 200) throw new Error(`Manifest download failed with HTTP ${response.status}`);
  return response.text;
}
async function loadPinnedEnvoyManifest() {
  let text = "";
  if (cfg.envoy.manifestPath && fs.existsSync(cfg.envoy.manifestPath)) text = fs.readFileSync(cfg.envoy.manifestPath, "utf8");
  else text = await fetchTextWithRedirects(cfg.envoy.manifestUrl);
  const digest = crypto.createHash("sha256").update(text).digest("hex");
  if (digest !== cfg.envoy.manifestSha256) throw new Error(`Envoy Gateway manifest digest mismatch: expected ${cfg.envoy.manifestSha256}, got ${digest}`);
  return text;
}
async function applyYamlDocuments(text, options = {}) {
  const documents = yaml.parseAllDocuments(text);
  const applied = [];
  for (const document of documents) {
    if (document.errors && document.errors.length) throw new Error(`Invalid YAML document: ${document.errors[0].message}`);
    const object = document.toJSON();
    if (!object || !object.kind) continue;
    if (options.source === "envoy" && object.kind === "CustomResourceDefinition"
      && String(object.metadata && object.metadata.name || "").endsWith(".gateway.networking.k8s.io")) {
      const existing = await k8sGet("apiextensions.k8s.io/v1", "CustomResourceDefinition", object.metadata.name, "").catch(() => null);
      if (existing) {
        node.warn(JSON.stringify({event:"pci.infrastructure.preserved",kind:"CustomResourceDefinition",name:object.metadata.name}));
        continue;
      }
    }
    applied.push(await k8sApply(object, object.metadata && object.metadata.namespace ? object.metadata.namespace : "", options));
  }
  return applied;
}
function gatewayAddress(gateway) {
  const addresses = gateway && gateway.status && Array.isArray(gateway.status.addresses) ? gateway.status.addresses : [];
  const preferred = addresses.find((entry) => entry.type === cfg.gatewayAddressType) || addresses[0];
  return preferred ? String(preferred.value || "") : "";
}
async function dnsMatchesHost(hostname, expectedAddress) {
  if (!hostname || !expectedAddress) return false;
  try {
    const addresses = await dns.promises.resolve4(hostname);
    return addresses.includes(expectedAddress);
  } catch {
    try {
      const aliases = await dns.promises.resolveCname(hostname);
      return aliases.some((alias) => alias.replace(/\.$/, "") === expectedAddress.replace(/\.$/, ""));
    } catch { return false; }
  }
}

// Only the helper's exact registered namespace is an external deletion target.
async function pciDeleteParticipant(tenant,parent){
  const data=parent?.data||{};let name=data.participant_namespace,role=data.participant_cleanup_role;
  if(!name&&!role){
    // Recover rc.4 crashes before registration. Read exact deterministic names;
    // never discover deletion targets through a mutable label selector.
    role='pci-participant-cleanup-'+tenant.tenant_id;
    const candidates=['pci-participant-'+tenant.tenant_id,'pci-participant-'+tenant.tenant_id.slice(0,8)];
    const found=[];
    for(const candidate of candidates){const r=await k8sRequest('GET','/api/v1/namespaces/'+candidate);if(r.status===200)found.push(candidate);else if(r.status!==404)throw new Error('PCI-PARTICIPANT-CLEANUP-ACCESS');}
    if(found.length>1)throw new Error('PCI-PARTICIPANT-REGISTRY');
    name=found[0]||candidates[0];
  }
  if(!['pci-participant-'+tenant.tenant_id,'pci-participant-'+tenant.tenant_id.slice(0,8)].includes(name)||role!=='pci-participant-cleanup-'+tenant.tenant_id)throw new Error('PCI-PARTICIPANT-REGISTRY');
  const targets=[['/api/v1/namespaces/'+encodeURIComponent(name),'namespace'],['/apis/rbac.authorization.k8s.io/v1/clusterroles/'+encodeURIComponent(role),'role']];
  const objects=[];
  for(const [path,kind]of targets){
    const r=await k8sRequest('GET',path);if(r.status===404){objects.push(null);continue;}if(r.status!==200)throw new Error('PCI-PARTICIPANT-CLEANUP-ACCESS');
    const m=r.data?.metadata,l=m?.labels||{};
    if(!m?.uid||!m.resourceVersion||l['xfsc.org/pci-tenant-id']!==tenant.tenant_id||l['xfsc.org/pci-owner-uid']!==tenant.owner_uid||l['xfsc.org/pci-install-uid']!==parent.metadata.uid||l['app.kubernetes.io/part-of']!=='fap-pci-reference')throw new Error('PCI-PARTICIPANT-OWNER');
    if(kind==='namespace'&&data.participant_namespace_uid&&data.participant_namespace_uid!==m.uid)throw new Error('PCI-PARTICIPANT-REPLACED');
    objects.push(r.data);
  }
  async function remove(index){const object=objects[index];if(!object)return;const m=object.metadata;await k8sExpect('DELETE',targets[index][0],{headers:{'content-type':'application/json'},body:JSON.stringify({apiVersion:'v1',kind:'DeleteOptions',preconditions:{uid:m.uid,resourceVersion:m.resourceVersion},propagationPolicy:'Foreground'})},[200,202,404]);}
  // Namespace deletion removes the Helm release record and all reference
  // workloads and trust. Do not erase the registry or its RBAC until GC ends.
  if(objects[0]){if(!objects[0].metadata.deletionTimestamp)await remove(0);return false;}
  if(objects[1])await remove(1); // its owner-referenced binding is collected
  return true;
}

return (async () => {
  const action = String(msg.pciAction || msg.type || "");

  async function currentStatus() {
    try {
      const row = (await getPool().query("SELECT state_value,updated_at FROM platform_state WHERE state_key='platform'"))?.rows?.[0];
      if (!row) {
        return {
          status: "GroundZeroRequired",
          ready: false,
          version: cfg.version,
          mainHost: cfg.mainHost,
          orceBasePath: cfg.orceBasePath,
          ocmNamespace: cfg.ocmNamespace,
          message: "Run ground-zero before importing the PCI flow.",
        };
      }
      const platform = { ...row.state_value, updatedAt: new Date(row.updated_at).toISOString() };
      const address = platform?.gateway?.address || "";
      if (address && platform.mainHost) {
        const dnsReady = await dnsMatchesHost(platform.mainHost, address).catch(() => false);
        platform.ready = Boolean(dnsReady);
        platform.status = dnsReady ? "Ready" : "DNSPending";
        if (Array.isArray(platform.conditions)) {
          platform.conditions = platform.conditions.map((condition) => condition.type === "MainDNSReady"
            ? {
                ...condition,
                status: dnsReady ? "True" : "False",
                reason: dnsReady ? "DNSMatchesGateway" : "DNSPending",
                message: dnsReady
                  ? "Main PCI DNS resolves to the Envoy Gateway."
                  : `DNS must resolve ${platform.mainHost} to ${address}.`,
              }
            : condition);
        }
      }
      return platform;
    } catch (error) {
      return {
        status: "GroundZeroRequired",
        ready: false,
        version: cfg.version,
        mainHost: cfg.mainHost,
        orceBasePath: cfg.orceBasePath,
        ocmNamespace: cfg.ocmNamespace,
        message: "PCI platform dependency check failed",
      };
    }
  }

  if (action === "platform.status") {
    const platform = await currentStatus();
    node.status({
      fill: platform.ready ? "green" : "yellow",
      shape: platform.ready ? "dot" : "ring",
      text: platform.status || "Unknown",
    });
    return emit(200, { platform }, {}, "pci:platform-status");
  }

  if (action === "platform.initialize") {
    if (!msg.pciInternal) await requireSession(["provider_admin"]);
    const platform = await currentStatus();
    node.status({
      fill: platform.ready ? "green" : "yellow",
      shape: platform.ready ? "dot" : "ring",
      text: platform.status || "GroundZeroRequired",
    });
    return emit(200, {
      platform,
      reconciliation: "status-only",
      message: "Cluster bootstrap is owned exclusively by ground-zero; M1 performs no infrastructure mutations.",
    }, {}, "pci:platform-status");
  }

  throw pciErrors.notFound("Unknown infrastructure action.");
})().catch((error) => {
  node.status({ fill: "red", shape: "ring", text: "PCI-PLATFORM-CHECK-FAILED" });
  return emitError(error);
});

const { URL, URLSearchParams } = url;
/**
 * Canonical public URL/base-path helpers shared by the browser bundle and the
 * generated ORCE Function nodes.
 *
 * PCI_ORCE_BASE_PATH is a path prefix, never a URL. All external URLs are HTTPS.
 */
const SAFE_BASE_SEGMENT = /^[A-Za-z0-9._~-]+$/;

function rejectUrlLikePath(raw, label) {
  if (/^[A-Za-z][A-Za-z0-9+.-]*:/.test(raw)) throw new Error(`${label} must be a path prefix, not a URL`);
  if (raw.startsWith("//")) throw new Error(`${label} must not be protocol-relative`);
  if (/[?#\\]/.test(raw)) throw new Error(`${label} must not contain query strings, fragments, or backslashes`);
  if (/\s|[\u0000-\u001F\u007F]/.test(raw)) throw new Error(`${label} must not contain whitespace or control characters`);
}

function normalizeBasePath(value = "") {
  const raw = String(value ?? "").trim();
  if (raw === "" || raw === "/") return "";
  rejectUrlLikePath(raw, "PCI_ORCE_BASE_PATH");

  const withLeadingSlash = raw.startsWith("/") ? raw : `/${raw}`;
  const normalized = withLeadingSlash.replace(/\/+$/, "");
  if (!normalized || normalized === "/") return "";
  if (normalized.includes("//")) throw new Error("PCI_ORCE_BASE_PATH must not contain empty path segments");

  const segments = normalized.slice(1).split("/");
  for (const segment of segments) {
    if (!segment || segment === "." || segment === "..") throw new Error("PCI_ORCE_BASE_PATH must not contain dot segments");
    if (segment.includes("%")) throw new Error("PCI_ORCE_BASE_PATH must not contain percent-encoded segments");
    if (!SAFE_BASE_SEGMENT.test(segment)) throw new Error(`PCI_ORCE_BASE_PATH contains an unsafe segment: ${segment}`);
  }
  return normalized;
}


function splitApplicationReference(value = "/") {
  const raw = String(value ?? "").trim();
  if (!raw) return { pathname: "/", suffix: "" };
  if (/^[A-Za-z][A-Za-z0-9+.-]*:/.test(raw)) throw new Error("application path must not be a URL");
  if (raw.startsWith("//")) throw new Error("application path must not be protocol-relative");
  if (/\\|\s|[\u0000-\u001F\u007F]/.test(raw)) throw new Error("application path must not contain backslashes, whitespace, or control characters");
  const queryIndex = raw.indexOf("?");
  const fragmentIndex = raw.indexOf("#");
  const indexes = [queryIndex, fragmentIndex].filter((index) => index >= 0);
  const boundary = indexes.length ? Math.min(...indexes) : raw.length;
  return { pathname: raw.slice(0, boundary) || "/", suffix: raw.slice(boundary) };
}

function normalizeApplicationPath(value = "/") {
  const raw = String(value ?? "").trim();
  if (!raw) return "/";
  rejectUrlLikePath(raw, "application path");

  const withLeadingSlash = raw.startsWith("/") ? raw : `/${raw}`;
  if (withLeadingSlash === "/") return "/";
  if (withLeadingSlash.includes("//")) throw new Error("application path must not contain empty path segments");

  const trailingSlash = withLeadingSlash.endsWith("/");
  const body = trailingSlash ? withLeadingSlash.slice(0, -1) : withLeadingSlash;
  const segments = body.slice(1).split("/");
  for (const segment of segments) {
    if (!segment) throw new Error("application path must not contain empty path segments");
    let decoded;
    try { decoded = decodeURIComponent(segment); } catch { throw new Error("application path contains invalid percent encoding"); }
    if (decoded === "." || decoded === ".." || decoded.includes("/") || decoded.includes("\\")) {
      throw new Error("application path must not contain encoded or literal traversal segments");
    }
  }
  return `${body}${trailingSlash ? "/" : ""}`;
}

function withBasePath(path, basePath = "") {
  const base = normalizeBasePath(basePath);
  const { pathname, suffix } = splitApplicationReference(path);
  const applicationPath = normalizeApplicationPath(pathname);
  let prefixed;
  if (!base) prefixed = applicationPath;
  else if (applicationPath === base || applicationPath.startsWith(`${base}/`)) prefixed = applicationPath;
  else if (applicationPath === "/") prefixed = `${base}/`;
  else prefixed = `${base}${applicationPath}`;
  return `${prefixed}${suffix}`;
}

function normalizePublicHost(value) {
  const raw = String(value ?? "").trim().toLowerCase().replace(/\.$/, "");
  if (!raw) throw new Error("public host is required");
  if (/^[A-Za-z][A-Za-z0-9+.-]*:/.test(raw) || raw.startsWith("//") || /[/?#@\\\s]/.test(raw)) {
    throw new Error("public host must be a hostname, not a URL");
  }

  const match = /^(.*?)(?::([0-9]{1,5}))?$/.exec(raw);
  const hostname = match ? match[1] : "";
  const port = match && match[2] ? Number(match[2]) : null;
  const validDns = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(hostname);
  if (!validDns || (port !== null && (port < 1 || port > 65535))) throw new Error("public host is invalid");
  return port === null ? hostname : `${hostname}:${port}`;
}

function publicOrigin(host) {
  return `https://${normalizePublicHost(host)}`;
}

function publicUrl(host, path = "/", basePath = "") {
  return `${publicOrigin(host)}${withBasePath(path, basePath)}`;
}

function uiPath(basePath = "") {
  return withBasePath("/ui/", basePath);
}

function apiPath(path = "/", basePath = "") {
  const suffix = normalizeApplicationPath(path);
  const apiRelative = suffix === "/" ? "/api/v1/" : `/api/v1${suffix}`;
  return withBasePath(apiRelative, basePath);
}

function uiUrl(host, basePath = "") {
  return publicUrl(host, "/ui/", basePath);
}

